export function translateStatic(language: Language, value: string): string {
  const direct = phraseTranslations[language][value] ?? supportPhraseTranslations[language][value] ?? dynamicPhraseTranslations[language][value];
  if (direct) return direct;
  if (value.startsWith('Добро пожаловать')) {
    const name = value.replace(/^Добро пожаловать\s*,?\s*/, '').replace(/[.]$/, '').trim();
    const localizedName = name === 'коллекционер' ? dynamicPhraseTranslations[language]['коллекционер'] : name;
    return language === 'uz-latn' ? `Xush kelibsiz${localizedName ? `, ${localizedName}` : ''}.` : language === 'uz-cyrl' ? `Хуш келибсиз${localizedName ? `, ${localizedName}` : ''}.` : value;
  }
  const statsMatch = value.match(/^Предметов: (\d+)$/); if (statsMatch) return language === 'uz-latn' ? `Buyumlar: ${statsMatch[1]}` : language === 'uz-cyrl' ? `Буюмлар: ${statsMatch[1]}` : value;
  const categoryStatsMatch = value.match(/^Категорий: (\d+) · Стран: (\d+)$/); if (categoryStatsMatch) return language === 'uz-latn' ? `Toifalar: ${categoryStatsMatch[1]} · Mamlakatlar: ${categoryStatsMatch[2]}` : language === 'uz-cyrl' ? `Тоифалар: ${categoryStatsMatch[1]} · Мамлакатлар: ${categoryStatsMatch[2]}` : value;
  const weightMatch = value.match(/^Общий вес (золота|серебра): (.+) г$/); if (weightMatch) { const metal = weightMatch[1] === 'золота' ? (language === 'uz-latn' ? 'oltin' : 'олтин') : (language === 'uz-latn' ? 'kumush' : 'кумуш'); return language === 'uz-latn' ? `Umumiy ${metal} og‘irligi: ${weightMatch[2]} g` : language === 'uz-cyrl' ? `Умумий ${metal} оғирлиги: ${weightMatch[2]} г` : value; }
  const estimateMatch = value.match(/^Оценка:\s*(.+)$/); if (estimateMatch) return language === 'uz-latn' ? `Baholash: ${estimateMatch[1]}` : language === 'uz-cyrl' ? `Баҳолаш: ${estimateMatch[1]}` : value;
  const createdMatch = value.match(/^Создана\s+(.+?)\s+·\s+(.+)$/); if (createdMatch) return language === 'uz-latn' ? `Yaratilgan ${createdMatch[1]} · ${createdMatch[2]}` : language === 'uz-cyrl' ? `Яратилган ${createdMatch[1]} · ${createdMatch[2]}` : value;
  const imageCountMatch = value.match(/^(\d+) изображени(е|я|й)$/); if (imageCountMatch) return language === 'uz-latn' ? `${imageCountMatch[1]} ta rasm` : language === 'uz-cyrl' ? `${imageCountMatch[1]} та расм` : value;
  const loadedItemsMatch = value.match(/^(\d+) предметов загружено$/); if (loadedItemsMatch) return language === 'uz-latn' ? `${loadedItemsMatch[1]} ta buyum yuklandi` : language === 'uz-cyrl' ? `${loadedItemsMatch[1]} та буюм юкланди` : value;
  const favoriteCategoryMatch = value.match(/^Любимая категория:\s*(.+)$/); if (favoriteCategoryMatch) return language === 'uz-latn' ? `Sevimli toifa: ${favoriteCategoryMatch[1]}` : language === 'uz-cyrl' ? `Севимли тоифа: ${favoriteCategoryMatch[1]}` : value;
  const stepMatch = value.match(/^ШАГ (\d+) ИЗ 3$/); if (stepMatch) return language === 'uz-latn' ? `${stepMatch[1]}-QADAM / 3` : language === 'uz-cyrl' ? `${stepMatch[1]}-БОСҚИЧ / 3` : value;
  const clarificationMatch = value.match(/^Требует уточнения:\s*(.+)$/); if (clarificationMatch) return language === 'uz-latn' ? `Aniqlashtirish kerak: ${clarificationMatch[1]}` : language === 'uz-cyrl' ? `Аниқлаш керак: ${clarificationMatch[1]}` : value;
  const priceFromMatch = value.match(/^от (.+)$/); if (priceFromMatch) return language === 'uz-latn' ? `dan ${priceFromMatch[1]}` : language === 'uz-cyrl' ? `${priceFromMatch[1]} дан` : value;
  const codeEmailMatch = value.match(/^Введите код, отправленный на\s+(.+)$/); if (codeEmailMatch) return language === 'uz-latn' ? `Quyidagi manzilga yuborilgan kodni kiriting: ${codeEmailMatch[1]}` : language === 'uz-cyrl' ? `Қуйидаги манзилга юборилган кодни киритинг: ${codeEmailMatch[1]}` : value;
  const catalogCountMatch = value.match(/^(\d+) правителей · (\d+) монет$/); if (catalogCountMatch) return language === 'uz-latn' ? `${catalogCountMatch[1]} hukmdor · ${catalogCountMatch[2]} tanga` : language === 'uz-cyrl' ? `${catalogCountMatch[1]} ҳукмдор · ${catalogCountMatch[2]} танга` : value;
  const imageHintMatch = value.match(/^(\d+) изображени(е|я|й) • нажмите на изображение для увеличения$/); if (imageHintMatch) return language === 'uz-latn' ? `${imageHintMatch[1]} ta rasm • kattalashtirish uchun rasmga bosing` : language === 'uz-cyrl' ? `${imageHintMatch[1]} та расм • катталаштириш учун расмни босинг` : value;
  const estimateLabelMatch = value.match(/^Ориентир:\s*(.+)$/); if (estimateLabelMatch) return language === 'uz-latn' ? `Mo‘ljal: ${estimateLabelMatch[1]}` : language === 'uz-cyrl' ? `Мўлжал: ${estimateLabelMatch[1]}` : value;
  const localizedSuffixMatch = value.match(/^(.+?) · (Ожидает|Получена|На проверке|Нужны сведения|Проверено|Одобрено|Отклонено|Завершено|Продано|Получен ответ|Золото|Серебро|Медь|Бронза|Металл не указан|Монетный двор не указан)$/);
  if (localizedSuffixMatch) {
    const suffix: string = translateStatic(language, localizedSuffixMatch[2]);
    return `${localizedSuffixMatch[1]} · ${suffix}`;
  }
  return value;
}

